const LANG=ls.get('lang','vi');
try{window.api&&api.setLang&&api.setLang(LANG)}catch(e){}
if(LANG==='en'&&window.I18N_EN){const VIRX=/[À-ỹđĐ]/,D=window.I18N_EN,PH=window.I18N_PH||[];document.documentElement.lang='en';
  const tr=(t,ph)=>{const k=t.trim();if(!k||!VIRX.test(k))return t;let r=D[k];if(r==null){const k2=k.replace(/\s*:$/,'');if(D[k2]!=null)r=D[k2]+(k2!==k?':':'');}
    if(r==null){const m=k.match(/^([^\p{L}\d(]+)(.+)$/u);if(m&&D[m[2].trim()]!=null)r=m[1]+D[m[2].trim()];}
    if(r==null){if(!ph)return t;r=k;for(const[a,b] of PH)if(r.includes(a))r=r.split(a).join(b);}return t.replace(k,r)};
  const inData=n=>{const td=n.parentElement&&n.parentElement.closest('tbody td, textarea, .clamp, #dPane .ph h2');return !!td};
  const node=n=>{if(n.nodeType===3){const v=n.nodeValue,x=tr(v,!inData(n));if(x!==v)n.nodeValue=x;return}
    if(n.nodeType!==1||/^(SCRIPT|STYLE|TEXTAREA)$/.test(n.tagName))return;
    for(const a of['placeholder','title'])if(n.hasAttribute(a)){const v=n.getAttribute(a),x=tr(v,true);if(x!==v)n.setAttribute(a,x)}
    if(n.tagName==='OPTION'&&n.firstChild){const v=n.textContent,x=tr(v,false);if(x!==v)n.textContent=x;return}
    for(const c of n.childNodes)node(c)};
  window.__tr=tr;const go=()=>{node(document.body);document.title=tr(document.title,true);new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')node(m.target);else{for(const a of m.addedNodes)node(a);if(m.type==='attributes')node(m.target)}}}).observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','title']})};
  document.readyState==='loading'?document.addEventListener('DOMContentLoaded',go):go();
  const A=window.alert.bind(window);window.alert=m=>A(tr(String(m),true));}
