  const pThu=ptNet('thu'),pTra=ptNet('tra'),eom=asOf===new Date(Date.UTC(+asOf.slice(0,4),+asOf.slice(5,7),0)).toISOString().slice(0,10),ok=Math.abs(pThu-thu)<0.01&&Math.abs(pTra-tra)<0.01;
