function lgBody(R,lim,all){const r=LGR,F=LGF,row=(x,child,par)=>{const i=r.rows.indexOf(x);return `<tr data-lg="${r.rows.indexOf(x)}" class="dbl${child?' lgChild':''}${x.outP?' lgOut':''}"${child?` data-lgpar="${esc(par)}" data-nosum="1" style="display:none;${x.status==='open'?'background:#FEF3F2':x.status==='check'?'background:#FFFAEB':''}"`:''}${x.status==='open'?' style="background:#FEF3F2"':x.status==='check'?' style="background:#FFFAEB"':''}><td><input type="checkbox" data-lgk="${r.rows.indexOf(x)}"></td><td class=nw style="${child?'padding-left:22px;color:#667085':''}">${esc(x.doc)}</td><td class=nw>${vn(x.d)}</td><td><div class=clamp title="${esc(x.ds)}">${esc(x.ds)}</div></td>${all?`<td style="font-size:11px">${esc(x.bp)}</td>`:''}<td>${esc(x.dr)}</td><td>${esc(x.cr)}</td><td class=n>${x.side==='dr'?fmt2(x.a):''}</td><td class=n>${x.side==='cr'?fmt2(x.a):''}</td><td class="n ${x.v<0?'neg':''}"><b>${fmt2(x.v)}</b></td><td class=nw>${lgStSel(x.status,`data-lgs="${r.rows.indexOf(x)}"`)}${x.manual?' <span class=mut title="sửa tay">✎</span>':''}</td><td style="font-size:11px">${x.grp?`<a href="#" data-lgg="${esc(x.grp)}">${esc(x.grp)}</a> · `:''}${x.status==='ok'&&x.grp?lgLink(x.grp,x.doc):''}${x.status!=='ok'&&!x.outP?`<button class="btn sm" data-lgsg="${r.rows.indexOf(x)}" style="padding:0 6px;font-size:11px" title="Gợi ý chứng từ đối ứng (phím G)">🔍 Gợi ý</button> `:''}${esc(x.how)}${x.status==='ok'&&Math.abs(x.gbal||0)>0.005?` <span class=neg title="Nhóm khớp này chưa cân Nợ = Có">⚠ nhóm lệch ${fmt2(x.gbal)}</span>`:''}${x.outP?' <span style="color:#667085">· dòng trước kỳ (đối ứng của nhóm khớp)</span>':x.gout?' <span style="color:#B54708" title="Dòng đối ứng nằm ngoài kỳ – xem ở bộ lọc Khớp">↔ đối ứng ngoài kỳ</span>':''}${x.status==='open'&&Math.abs((x.left||0)-x.v)>0.004?` · còn ${fmt2(x.left)}`:''}</td><td><input class="lgNote" list="lgNotes" data-lgn="${r.rows.indexOf(x)}" value="${esc(x.note)}" style="width:180px;font-size:12px"></td></tr>`};
  const key=v=>[-Math.round(Math.abs(v)*100),v<0?0:1];
  if(F.sort==='grp'&&!F.grp){const GI=new Map();for(const x of R){const g=x.grp||('~'+x.id+x.side);const o=GI.get(g)||GI.set(g,{d:x.d,xs:[]}).get(g);o.xs.push(x);if(x.d<o.d)o.d=x.d}
    const PAL=['#FA4700','#1570EF','#17B26A','#9E77ED','#F79009','#06AED4','#EE46BC','#669F2A'],BG=['#FFF6F2','#EFF4FF','#ECFDF3','#F4F3FF','#FFFAEB','#ECFDFF','#FDF2FA','#F3FEE7'];let k=0,out='',n=0;
    for(const [g,o] of [...GI].sort((a,b)=>(a[0].startsWith('~'))-(b[0].startsWith('~'))||a[1].d.localeCompare(b[1].d)||a[0].localeCompare(b[0]))){if(n>lim)break;const real=!g.startsWith('~');
      if(real&&o.xs.length>1){const c=k%PAL.length;k++;const net=o.xs.reduce((q,x)=>q+x.v,0);out+=`<tr data-nosum="1" style="background:${BG[c]}"><td colspan=${all?14:13} style="border-left:4px solid ${PAL[c]};font-size:12px;padding:4px 10px"><b style="color:${PAL[c]}">Nhóm ${esc(g)}</b> · ${o.xs.length} dòng · ${esc(o.xs[0].how||'')} · Nợ − Có = <b class="${Math.abs(net)>0.005?'neg':''}">${fmt2(net)}</b>${Math.abs(net)<=0.005?' ✅':''}</td></tr>`;
        out+=o.xs.sort((a,b)=>a.d.localeCompare(b.d)||a.id-b.id).map(x=>row(x,false).replace('<tr ',`<tr data-gc="${PAL[c]}" style="box-shadow:inset 4px 0 0 ${PAL[c]};background:${BG[c]}" `)).join('')}
      else out+=o.xs.map(x=>row(x,false)).join('');n+=o.xs.length}
    return out}
  if(!F.grp){let L=R.slice();if(F.sort==='amt')L.sort((a,b)=>{const A=key(a.v),B=key(b.v);return A[0]-B[0]||A[1]-B[1]||a.d.localeCompare(b.d)});return L.slice(0,lim).map(x=>row(x,false)).join('')+(R.length>lim?`<tr><td colspan=13 class=mut style="text-align:center">… còn ${num(R.length-lim)} dòng – lọc theo tình trạng để xem</td></tr>`:'')}
  const G=new Map();for(const x of R){const k=x.doc||('#'+x.id);(G.get(k)||G.set(k,[]).get(k)).push(x)}
  let U=[...G].map(([doc,xs])=>{const dr=xs.filter(x=>x.side==='dr').reduce((q,x)=>q+x.a,0),cr=xs.filter(x=>x.side==='cr').reduce((q,x)=>q+x.a,0),last=xs.reduce((a,x)=>x.d>a.d||(x.d===a.d&&x.id>a.id)?x:a,xs[0]),st=xs.some(x=>x.status==='open')?'open':xs.some(x=>x.status==='check')?'check':'ok';
    return {doc,xs,dr,cr,net:dr-cr,d:xs[0].d,last,st,acD:[...new Set(xs.map(x=>x.dr))],acC:[...new Set(xs.map(x=>x.cr))],note:[...new Set(xs.map(x=>x.note).filter(Boolean))].join('; ')}});
  if(F.sort==='grp'){const fd=new Map();for(const u of U){u.g=(u.xs.find(x=>x.grp)||{}).grp||'';if(u.g&&(!fd.has(u.g)||u.d<fd.get(u.g)))fd.set(u.g,u.d)}U.sort((a,b)=>(!a.g)-(!b.g)||(fd.get(a.g)||'').localeCompare(fd.get(b.g)||'')||a.g.localeCompare(b.g)||a.d.localeCompare(b.d))}
  if(F.sort==='amt')U.sort((a,b)=>{const A=key(Math.abs(a.net)>0.004?a.net:a.dr),B=key(Math.abs(b.net)>0.004?b.net:b.dr);return (Math.abs(a.net)<=0.004)-(Math.abs(b.net)<=0.004)||A[0]-B[0]||A[1]-B[1]||a.d.localeCompare(b.d)});
  const PAL=['#FA4700','#1570EF','#17B26A','#9E77ED','#F79009','#06AED4','#EE46BC','#669F2A'],BG=['#FFF6F2','#EFF4FF','#ECFDF3','#F4F3FF','#FFFAEB','#ECFDFF','#FDF2FA','#F3FEE7'],GM=new Map(),GC=g=>{if(!GM.has(g)){const i=GM.size%PAL.length;GM.set(g,[PAL[i],BG[i]])}return GM.get(g)};
  let n=0,out='';for(const u of U){if(n>lim)break;
    if(u.xs.length===1){const x=u.xs[0],c=x.status==='ok'&&x.grp?GC(x.grp):null;out+=c?row(x,false).replace('<tr ',`<tr style="box-shadow:inset 4px 0 0 ${c[0]};background:${c[1]}" title="Nhóm khớp ${esc(x.grp)}" `):row(x,false);n++;continue}
    const hw=[...new Set(u.xs.map(x=>x.how))];
    const gk=(u.xs.find(x=>x.grp)||{}).grp||'',gc=u.st==='ok'&&gk?GC(gk):null;
    out+=`<tr class="dbl lgGrpRow" data-lgdoc="${esc(u.doc)}" style="font-weight:600;background:${gc?gc[1]:u.st==='open'?'#FEF3F2':u.st==='check'?'#FFFAEB':'#F9FAFB'};${gc?`box-shadow:inset 4px 0 0 ${gc[0]};`:''}cursor:pointer" title="${gk?'Nhóm khớp '+esc(gk):''}"><td><input type="checkbox" data-lgdc="${esc(u.doc)}"></td><td class=nw><span class="lgArr">▸</span> ${esc(u.doc)} <span class="badge b-L" style="font-size:10px">${u.xs.length} dòng</span></td><td class=nw>${vn(u.d)}${u.last.d!==u.d?' – '+vn(u.last.d):''}</td><td><div class=clamp title="${esc(u.last.ds)}">${esc(u.last.ds)}</div></td>${all?`<td style="font-size:11px">${esc([...new Set(u.xs.map(x=>x.bp))].join(', '))}</td>`:''}<td style="font-size:12px">${esc(u.acD.join(', '))}</td><td style="font-size:12px">${esc(u.acC.join(', '))}</td><td class=n>${u.dr?fmt2(u.dr):''}</td><td class=n>${u.cr?fmt2(u.cr):''}</td><td class="n ${u.net<0?'neg':''}"><b>${fmt2(u.net)}</b></td><td class=nw>${lgStSel(u.st,`data-lgsd="${esc(u.doc)}"`)}</td><td style="font-size:11px">${u.st==='ok'&&(u.xs.find(x=>x.grp)||{}).grp?lgLink(u.xs.find(x=>x.grp).grp,u.doc):''}${esc(hw.slice(0,2).join(' · '))}${hw.length>2?'…':''}</td><td style="font-size:12px">${esc(u.note)}</td></tr>`;
    out+=u.xs.map(x=>row(x,true,u.doc)).join('');n+=u.xs.length}
  return out+(n>lim?`<tr><td colspan=13 class=mut style="text-align:center">… còn thêm dòng – lọc theo tình trạng để xem</td></tr>`:'')}

/* v4.71: ô chọn tình trạng ngay trên dòng */
function lgStSel(st,attr){return `<select class="lgStSel" ${attr} style="font-size:12px;padding:2px 22px 2px 8px;height:28px;border-radius:14px;font-weight:600;${lgStCss(st)}" onclick="event.stopPropagation()"><option value="ok" ${st==='ok'?'selected':''}>✅ Khớp</option><option value="check" ${st==='check'?'selected':''}>⚠ Cần phân tích</option><option value="open" ${st==='open'?'selected':''}>❌ Chưa khớp</option><option value="auto">↺ Tự động</option></select>`}
function lgStCss(st){return st==='ok'?'background:#ECFDF3;color:#067647;border-color:#ABEFC6':st==='check'?'background:#FFFAEB;color:#B54708;border-color:#FEDF89':'background:#FEF3F2;color:#B42318;border-color:#FECDCA'}
function lgStColor(el){el.style.cssText=el.style.cssText.replace(/background:[^;]*;color:[^;]*;border-color:[^;]*/,'')+';'+lgStCss(el.value)}

