    <label>${TT('Tình trạng','Status')} <select id="p2S"><option value="">${TT('Tất cả còn dư','All with balance')}</option><option value="iss" ${P2F.st==='iss'?'selected':''}>⚠ ${TT('Có sai sót phân bổ (sai kỳ, chậm kỳ, dồn kỳ, sai số tiền…)','Amortisation errors (wrong period, late, lumped, wrong amount…)')}</option><option value="bad" ${P2F.st==='bad'?'selected':''}>${TT('Cần xử lý (hết kỳ / chưa phân bổ / vượt / chậm)','Needs action')}</option>${Object.entries(P2ST).map(([k,v])=>`<option value="${k}" ${P2F.st===k?'selected':''}>${v[0]} ${v[1]}</option>`).join('')}</select></label>
