  T.querySelectorAll('.cxI').forEach(x=>{x.onchange=async()=>{await aq('cxCell',+x.dataset.id,x.dataset.k,x.value.replace(/,/g,''),x.dataset.i!=null?+x.dataset.i:null);const sc=$('#cxT').closest('.tbl'),st=sc.scrollTop,sl=sc.scrollLeft;await vCX();const s2=$('#cxT').closest('.tbl');s2.scrollTop=st;s2.scrollLeft=sl};x.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();x.blur()}}});
